try {
    var payload = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
    var btc = Number(payload.price_btc);
    var eth = Number(payload.price_eth);
    var btcSymbol = payload.symbol_btc || 'BTCEUR';
    var ethSymbol = payload.symbol_eth || 'ETHEUR';

    function validSymbol(value) {
        return typeof value === 'string' && /^[A-Z0-9:_-]{3,20}$/.test(value);
    }

    if (!validSymbol(btcSymbol) || !validSymbol(ethSymbol)) {
        return null;
    }
    if (!Number.isFinite(btc) || !Number.isFinite(eth) || btc <= 0 || eth <= 0) {
        return null;
    }

    msg.payload = [
        'crypto,symbol=' + btcSymbol + ' price=' + btc,
        'crypto,symbol=' + ethSymbol + ' price=' + eth
    ].join('\n');
    msg.headers = {
        'Authorization': 'Token mytoken123',
        'Content-Type': 'text/plain; charset=utf-8'
    };
    return msg;
} catch (err) {
    node.warn('Invalid crypto payload: ' + err.message);
    return null;
}
